// Un item por negocio: destinatario, asunto, tabla HTML y el resumen que lee Gemini.
const negocios = $input.first().json.negocios || [];

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const num = (x) => (x === null || x === undefined ? '-' : String(Number(x)));
const celda = 'padding:6px 10px;border-bottom:1px solid #ddd';

return negocios.map((n) => {
  const filas = n.productos.map((p) => '<tr>'
    + '<td style="' + celda + '">' + esc(p.nombre) + '</td>'
    + '<td style="' + celda + ';text-align:right">' + num(p.stock_actual) + ' ' + esc(p.unidad) + '</td>'
    + '<td style="' + celda + ';text-align:right">' + num(p.stock_minimo) + ' ' + esc(p.unidad) + '</td>'
    + '<td style="' + celda + ';text-align:right"><b>' + num(p.deficit) + ' ' + esc(p.unidad) + '</b></td>'
    + '</tr>').join('');

  const uno = n.productos.length === 1;
  const tabla_html = '<p>Hola ' + esc(n.dueno.nombre) + ',</p>'
    + '<p>' + (uno ? 'Este producto de' : 'Estos productos de') + ' <b>' + esc(n.negocio.nombre)
    + '</b> ' + (uno ? 'está' : 'están') + ' por debajo de su stock mínimo:</p>'
    + '<table style="border-collapse:collapse;font-family:sans-serif;font-size:14px">'
    + '<tr style="background:#f3f3f3"><th style="padding:6px 10px;text-align:left">Producto</th>'
    + '<th style="padding:6px 10px;text-align:right">Stock actual</th>'
    + '<th style="padding:6px 10px;text-align:right">Mínimo</th>'
    + '<th style="padding:6px 10px;text-align:right">Falta</th></tr>'
    + filas + '</table>';

  return { json: {
    destinatario: n.dueno.email,
    asunto: uno
      ? 'Stock bajo: ' + n.productos[0].nombre
      : 'Stock bajo: ' + n.productos.length + ' productos en ' + n.negocio.nombre,
    negocio: n.negocio.nombre,
    tabla_html,
    resumen: n.productos.map((p) => ({
      producto: p.nombre,
      stock_actual: num(p.stock_actual),
      stock_minimo: num(p.stock_minimo),
      deficit: num(p.deficit),
      unidad: p.unidad,
    })),
  } };
});

// Texto de Gemini + tabla. Si Gemini falló o vino vacío, sale solo la tabla.
const base = $('Un correo por negocio').item.json;
const r = $input.item.json;
const partes = r.content?.parts || r.candidates?.[0]?.content?.parts || [];
const texto = partes.filter((p) => typeof p.text === 'string' && !p.thought)
  .map((p) => p.text).join('').trim();

const esc = (s) => String(s).replace(/[&<>"']/g, (c) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// La salida del modelo es texto no confiable: se escapa y solo se conservan los saltos de línea.
const bloqueIa = texto
  ? '<div style="font-family:sans-serif;font-size:14px;line-height:1.5">'
    + esc(texto).replace(/\n/g, '<br>') + '</div><hr style="margin:16px 0;border:0;border-top:1px solid #ddd">'
  : '';

return { json: {
  destinatario: base.destinatario,
  asunto: base.asunto,
  html: bloqueIa + base.tabla_html,
  con_ia: Boolean(texto),
} };
